import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"Promotion messaging and platform copy skeletons","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/kits/promotion.md","filePath":"en/modules/kits/promotion.md","lastUpdated":0}`),a={name:`en/modules/kits/promotion.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="promotion-messaging-and-platform-copy-skeletons" tabindex="-1">Promotion messaging and platform copy skeletons <a class="header-anchor" href="#promotion-messaging-and-platform-copy-skeletons" aria-label="Permalink to “Promotion messaging and platform copy skeletons”">​</a></h1><p>This page is the baseline for public release copy. All copy is governed by <a href="./verification.html">Verification status</a>: <strong>pending items must never be presented as verified</strong>. The skeletons below are marked &quot;finalize after live tests&quot; and only go out once the tests pass</p><h2 id="main-message-one-plugin-instead-of-five" tabindex="-1">Main message: one plugin instead of five <a class="header-anchor" href="#main-message-one-plugin-instead-of-five" aria-label="Permalink to “Main message: one plugin instead of five”">​</a></h2><p>One EmakiKits covers five kit needs without installing single-purpose plugins:</p><table tabindex="0"><thead><tr><th>Need covered</th><th>Capability</th></tr></thead><tbody><tr><td>Daily / weekly / monthly rewards</td><td><code>daily</code> / <code>weekly</code> / <code>monthly</code> cyclic kits</td></tr><tr><td>CDK redemption</td><td><code>cdk</code> kits (once server-wide / counted per player)</td></tr><tr><td>Starter kits</td><td><code>join</code> kits (with invite-code binding)</td></tr><tr><td>Choice kits</td><td><code>choice</code> kits (inline GUI)</td></tr><tr><td>Invite rewards</td><td><code>invite</code> kits plus the invite leaderboard</td></tr></tbody></table><p>Messaging red lines:</p><ul><li>Sign-in gameplay is not a selling point (EmakiKits explicitly does not do sign-in, see <a href="./scope.html">Scope and boundaries</a>); never list sign-in in copy</li><li>Never write &quot;standalone / no dependencies / lite mode&quot;; disclose the EmakiCoreLib hard dependency honestly</li><li>Write &quot;pending live tests&quot; for untested capabilities; never write &quot;verified / runs stably&quot;. &quot;Not documented&quot; does not mean &quot;absent&quot;, and &quot;implemented&quot; does not mean &quot;live-tested&quot;</li></ul><h2 id="platform-copy-skeletons-finalize-after-live-tests" tabindex="-1">Platform copy skeletons (finalize after live tests) <a class="header-anchor" href="#platform-copy-skeletons-finalize-after-live-tests" aria-label="Permalink to “Platform copy skeletons (finalize after live tests)”">​</a></h2><h3 id="minebbs-chinese" tabindex="-1">MineBBS (Chinese) <a class="header-anchor" href="#minebbs-chinese" aria-label="Permalink to “MineBBS (Chinese)”">​</a></h3><ul><li>One line: A configuration-driven kit module: join, invite, daily, weekly, monthly, CDK, choice, and generic kits in one plugin</li><li>Points: one kit per YAML file; four reward types (items, money, nested kits, action pipelines); idempotency keys + audit + atomic writes; full in-game GUI editor; random-reward pity; invite leaderboard; Paper 26.1+ and Folia</li><li>Dependency disclosure: hard dependency on EmakiCoreLib (same family, providing item sources, action pipelines, GUI, and the economy bridge); optional PlaceholderAPI (the <code>%emakikits_invited%</code> placeholder)</li><li>Version: 1.0.6</li></ul><h3 id="spigotmc-english" tabindex="-1">SpigotMC (English) <a class="header-anchor" href="#spigotmc-english" aria-label="Permalink to “SpigotMC (English)”">​</a></h3><ul><li>One line: A configuration-driven kit plugin: join, invite, daily, weekly, monthly, CDK, choice and generic kits in one place</li><li>Points: one kit per YAML file; four reward types (items, money, nested kits, CoreLib action lines); idempotent claims with audit records and atomic writes; in-game GUI editor; random-reward pity; invite leaderboard with PlaceholderAPI support</li><li>Dependency disclosure: requires EmakiCoreLib (same ecosystem); PlaceholderAPI optional</li><li>Format: convert to the channel&#39;s BBCode; facts stay identical to the MineBBS entries</li></ul><h3 id="modrinth-markdown" tabindex="-1">Modrinth (Markdown) <a class="header-anchor" href="#modrinth-markdown" aria-label="Permalink to “Modrinth (Markdown)”">​</a></h3><ul><li>One line: same as SpigotMC</li><li>Points: same as SpigotMC, as a Markdown list</li><li>Version and compatibility baseline: 1.0.6, Paper 26.1+ (Folia supported); cite <a href="./verification.html">Verification status</a> for test status and never claim untested things</li></ul>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};